Object.assign(G.EXPLAIN.fr.confusableNotes, {
"affect|effect": "affect est un verbe : « avoir un effet sur » (Pollution affects health.) ; effect est surtout un nom : « effet » (Pollution has an effect on health.).",
"consequent|subsequent": "consequent = qui découle de ce qui précède (consequent job losses) ; subsequent = qui vient après, sans être forcément une conséquence (in subsequent years).",
"considerable|considerate": "considerable = important, assez grand (a considerable amount) ; considerate = attentionné, se dit d'une personne (a considerate neighbour).",
"consistent|constant": "consistent = cohérent, régulier (consistent results) ; constant = qui ne change pas ou qui ne s'arrête pas (a constant temperature, constant noise).",
"ensure|insure": "ensure = s'assurer que quelque chose arrive (ensure safety) ; insure = assurer auprès d'une compagnie d'assurance (insure a car against theft).",
"equal|equate": "equal est un adjectif : « égal » (equal rights) ; equate est un verbe : « assimiler », souvent equate A with B (Many people equate wealth with success.).",
"imply|inference": "imply : c'est l'auteur ou les données qui sous-entendent ; infer (nom inference) : c'est le lecteur qui en déduit. The data imply a link; we infer a link from the data.",
"maximise|minimise": "maximise = rendre le plus grand possible ; minimise = rendre le plus petit possible. Regardez le début : max- (maximum) et min- (minimum).",
"principal|principle": "principle est un nom : « principe » (the principle of equality) ; principal = « directeur d'école », ou adjectif « principal » (the principal reason).",
"precede|proceed": "precede = venir avant (The storm preceded the flood.) ; proceed = continuer, se rendre (Please proceed to gate 5.). pre- = avant, pro- = en avant.",
"cite|site": "cite est un verbe : « citer » (cite a source) ; site est un nom : « site, emplacement » (a building site). Même prononciation, nature différente.",
"cite|sight": "cite = citer (cite evidence) ; sight = la vue, ce que l'on voit (lose your sight). Les deux se prononcent exactement pareil.",
"comprehension|comprehensive": "comprehension est un nom : « compréhension » (reading comprehension) ; comprehensive est un adjectif : « complet, exhaustif » (a comprehensive review). Attention : il ne veut pas dire « compréhensif ».",
"emigrate|immigrate": "emigrate = quitter son pays (e- = hors de) ; immigrate = s'installer dans un autre pays (im- = dans) : She emigrated from Thailand and immigrated to Canada.",
"immigrate|migrate": "migrate = se déplacer en général, pour des personnes, des animaux ou des oiseaux ; immigrate = venir s'installer dans un autre pays.",
"emigrate|migrate": "migrate = migrer en général (les oiseaux migrent aussi) ; emigrate = quitter son pays pour aller vivre ailleurs durablement.",
"censor|censure": "censor = censurer un contenu (censor a film) ; censure = blâmer officiellement (The minister was censured by parliament.). Attention au faux ami.",
"censor|sensor": "censor = censurer ; sensor = capteur (a motion sensor). Même prononciation : c'est le sens qui décide.",
"convince|persuade": "convince = faire croire (convince someone that something is true) ; persuade = décider quelqu'un à agir (persuade someone to do something).",
"access|assess": "access = accès (access to clean water) ; assess = évaluer (assess students’ progress). Orthographe : ac-cess et as-sess.",
"access|excess": "access = accès ; excess = excès (an excess of sugar). Sons proches : ac- et ex-.",
"adapt|adopt": "adapt = (s')adapter (adapt to a new climate) ; adopt = adopter une idée ou un enfant (adopt a new policy).",
"altar|alter": "alter est un verbe : « modifier » (alter a plan) ; altar est un nom : « autel ». Même prononciation.",
"dedicate|devote": "Les deux veulent dire « consacrer » et se construisent avec to + nom ou -ing ; mais dedicate sert aussi à dédier un livre ou un bâtiment (The book is dedicated to her mother.).",
"discreet|discrete": "discrete = distinct, séparé (discrete categories) ; discreet = discret, prudent (a discreet enquiry). Même prononciation.",
"explicit|implicit": "explicit = dit clairement ; implicit = sous-entendu, pas dit directement (an implicit assumption).",
"external|internal": "external = externe (external examiners) ; internal = interne (internal organs). Ce sont des contraires.",
"implication|imply": "imply est un verbe : « sous-entendre » ; implication est un nom : « conséquence, implication » (the implications of the policy).",
"maximise|minimum": "maximise est un verbe : « maximiser » ; maximum et minimum sont des noms : « le maximum / le minimum » (a minimum of ten people).",
"assume|presume": "assume = supposer, même sans preuve ; presume = présumer, avec de bonnes raisons. Sens très proches, presume est un peu plus sûr de lui.",
"prior|priority": "prior est un adjectif : « antérieur », souvent prior to = « avant » (prior to the exam) ; priority est un nom : « priorité » (a top priority).",
"eventual|ultimately": "eventually = finalement, au bout d'un certain temps (faux ami : pas « éventuellement ») ; ultimately = en fin de compte, au fond (Ultimately, the decision is yours.).",
"acute|chronic": "acute = aigu, soudain et grave ; chronic = chronique, qui dure longtemps (chronic back pain). Ce sont des contraires en médecine.",
"epidemic|pandemic": "epidemic = épidémie dans une région ou un pays ; pandemic = pandémie, répandue dans le monde entier (pan- = tout).",
"prescribe|proscribe": "prescribe = prescrire (un médicament, une règle) ; proscribe = interdire officiellement. Sens presque opposés.",
"astrology|astronomy": "astronomy = l'astronomie, une science ; astrology = l'astrologie, qui prédit l'avenir d'après les astres, pas une science.",
"qualitative|quantitative": "qualitative = qualitatif, par exemple des entretiens ou des opinions ; quantitative = quantitatif, avec des chiffres (quantity = quantité).",
"microscope|telescope": "microscope = pour voir le très petit (micro- = petit) ; telescope = pour voir le très lointain (tele- = loin).",
"endangered|extinct": "endangered = menacé, il en reste encore ; extinct = éteint, disparu, il n'en reste aucun.",
"assure|ensure": "assure s'adresse à une personne : « assurer quelqu'un » (I assure you that…) ; ensure = faire en sorte que quelque chose arrive (ensure that the data are accurate).",
"assure|insure": "assure = assurer quelqu'un de quelque chose ; insure = assurer un bien auprès d'un assureur (insure your home against fire).",
"complement|compliment": "complement = compléter, mettre en valeur (The sauce complements the meal.) ; compliment = un compliment (pay someone a compliment). complEment rend complEte.",
"visible|visual": "visible = qu'on peut voir (visible from space) ; visual = visuel (visual aids, visual art).",
"hardware|software": "hardware = le matériel, ce qu'on peut toucher (écran, clavier) ; software = le logiciel. Les deux sont indénombrables : jamais de -s.",
"persecute|prosecute": "prosecute = poursuivre en justice ; persecute = persécuter un groupe de personnes.",
"export|import": "export = exporter (ex- = vers l'extérieur) ; import = importer (im- = vers l'intérieur).",
"salary|wage": "salary = salaire fixe, mensuel ou annuel ; wage = paie calculée à l'heure, au jour ou à la semaine (the minimum wage).",
"fair|fare": "fare est un nom : « prix du billet » (bus fare) ; fair est un adjectif : « juste » (a fair system). Même prononciation.",
"sight|site": "site = lieu, emplacement (a construction site) ; sight = la vue, ou ce qu'il faut voir (the sights of London). Même prononciation.",
});
